     9	} from "./common";
    10	import type { Role } from "./member";
    11	import type { ProjectVisibility } from "./project";
    12	
    13	/**
    14	 * The complete action vocabulary of `can()`. Every authorization decision in
    15	 * Taskflow names one of these — there is no free-form string permission.
    16	 */
    17	export type PermissionAction =
    18	  | "org:read"
    19	  | "org:update"
    20	  | "org:delete"
    21	  | "org:manage_billing"
    22	  | "org:manage_flags"
    23	  | "member:read"
    24	  | "member:invite"
    25	  | "member:update_role"
    26	  | "member:remove"
    27	  | "project:create"
    28	  | "project:read"
    29	  | "project:update"
    30	  | "project:archive"
    31	  | "project:delete"
    32	  | "issue:create"
    33	  | "issue:read"
    34	  | "issue:update"
    35	  | "issue:assign"
    36	  | "issue:archive"
    37	  | "issue:delete"
    38	  | "comment:create"
    39	  | "comment:read"
    40	  | "comment:update"
    41	  | "comment:delete"
    42	  | "activity:read"
    43	  | "activity:export"
    44	  | "notification:read"
    45	  | "notification:manage"
    46	  | "webhook:manage";
    47	
    48	/**
    49	 * The object a permission is asked about. Discriminated on `kind` so the
    50	 * ownership rules inside `can()` can read the fields they need without casts.
    51	 */
    52	export type PermissionResource =
    53	  | { readonly kind: "organization"; readonly orgId: OrgId }
    54	  | { readonly kind: "billing"; readonly orgId: OrgId }
    55	  | {
    56	      readonly kind: "member";
    57	      readonly orgId: OrgId;
    58	      readonly memberId: MemberId;
    59	      readonly targetUserId: UserId;
    60	      readonly targetRole: Role;
    61	    }
    62	  | {
    63	      readonly kind: "project";
    64	      readonly orgId: OrgId;
    65	      readonly projectId: ProjectId;
    66	      readonly visibility: ProjectVisibility;
    67	      readonly leadId: UserId | null;
    68	    }
    69	  | {
    70	      readonly kind: "issue";
    71	      readonly orgId: OrgId;
    72	      readonly projectId: ProjectId;
    73	      readonly issueId: IssueId;
    74	      readonly authorId: UserId;
    75	      readonly assigneeId: UserId | null;
    76	    }
    77	  | {
    78	      readonly kind: "comment";
    79	      readonly orgId: OrgId;
    80	      readonly commentId: CommentId;
    81	      readonly authorId: UserId;
    82	    }
    83	  | { readonly kind: "activity"; readonly orgId: OrgId }
    84	  | { readonly kind: "notification"; readonly orgId: OrgId; readonly recipientId: UserId }
    85	  | { readonly kind: "webhook"; readonly orgId: OrgId; readonly webhookId: WebhookId | null };
    86	
    87	export type PermissionResourceKind = PermissionResource["kind"];
    88	
    89	/** Verbose form of a decision, used by the settings UI to explain a denial. */
    90	export interface PermissionDecision {
    91	  readonly allowed: boolean;
    92	  readonly action: PermissionAction;
    93	  readonly resourceKind: PermissionResourceKind;
    94	  readonly reason:
    95	    | "granted_by_role"
    96	    | "granted_by_ownership"
    97	    | "granted_by_staff"
    98	    | "denied_by_role"
    99	    | "denied_cross_tenant"
   100	    | "denied_unknown_action";
