=== src/schemas/common.ts
     1	import { z } from "zod";
     2	import type {
     3	  ActivityId,
     4	  AttachmentId,
     5	  CommentId,
     6	  InvitationId,
     7	  IsoTimestamp,
     8	  IssueId,
     9	  LabelId,
    10	  MemberId,
    11	  NotificationId,
    12	  OrgId,
    13	  ProjectId,
    14	  SubscriptionId,
    15	  UserId,
    16	  WebhookId,
    17	} from "@/types/common";
    18	
    19	/**
    20	 * Shared Zod primitives.
    21	 *
    22	 * Every schema in `src/schemas` is used twice: by `react-hook-form` through
    23	 * `@hookform/resolvers/zod` on the client, and by the matching Server Action
    24	 * on the server. Keep them free of server-only imports.
    25	 */
    26	
    27	const ULID = /^[0-9A-HJKMNP-TV-Z]{26}$/i;
    28	
    29	/** Builds a branded-id schema whose output type is the branded alias. */
    30	function brandedId<T extends string>(label: string) {
    31	  return z
    32	    .string()
    33	    .regex(ULID, `${label} must be a ULID`)
    34	    .transform((value) => value as T);
    35	}
    36	
    37	export const userIdSchema = brandedId<UserId>("userId");
    38	export const orgIdSchema = brandedId<OrgId>("orgId");
    39	export const projectIdSchema = brandedId<ProjectId>("projectId");
    40	export const issueIdSchema = brandedId<IssueId>("issueId");
    41	export const commentIdSchema = brandedId<CommentId>("commentId");
    42	export const memberIdSchema = brandedId<MemberId>("memberId");
    43	export const notificationIdSchema = brandedId<NotificationId>("notificationId");
    44	export const activityIdSchema = brandedId<ActivityId>("activityId");
    45	export const invitationIdSchema = brandedId<InvitationId>("invitationId");
    46	export const labelIdSchema = brandedId<LabelId>("labelId");
    47	export const attachmentIdSchema = brandedId<AttachmentId>("attachmentId");
    48	export const subscriptionIdSchema = brandedId<SubscriptionId>("subscriptionId");
    49	export const webhookIdSchema = brandedId<WebhookId>("webhookId");
    50	
    51	export const isoTimestampSchema = z
    52	  .iso
    53	  .datetime()
    54	  .transform((value) => value as IsoTimestamp);
    55	
    56	export const emailSchema = z.email().max(254).toLowerCase();
    57	
    58	export const sortDirectionSchema = z.enum(["asc", "desc"]);
    59	
    60	export const pageRequestSchema = z.object({
    61	  limit: z.number().int().min(1).max(100).default(25),
    62	  cursor: z.string().nullable().optional(),
    63	});
    64	
    65	export const archiveScopeSchema = z.object({
    66	  includeArchived: z.boolean().optional(),
    67	});
    68	
    69	export const hexColorSchema = z
    70	  .string()
    71	  .regex(/^#[0-9a-fA-F]{6}$/, "must be a #rrggbb color");
    72	
    73	export type PageRequestInput = z.infer<typeof pageRequestSchema>;
    74	export type ArchiveScopeInput = z.infer<typeof archiveScopeSchema>;
