    74	  enterprise: {
    75	    plan: "enterprise",
    76	    seats: UNLIMITED,
    77	    projects: UNLIMITED,
    78	    issuesPerProject: UNLIMITED,
    79	    storageMb: 500_000,
    80	    apiRequestsPerHour: 100_000,
    81	    webhooks: UNLIMITED,
    82	    retentionDays: 2_555,
