import type {
  IsoTimestamp,
  OrgId,
  SubscriptionId,
  TenantScoped,
  Timestamps,
} from "./common";

export type PlanId = "free" | "starter" | "growth" | "enterprise";

export const PLAN_IDS: readonly PlanId[] = [
  "free",
  "starter",
  "growth",
  "enterprise",
];

export type BillingInterval = "monthly" | "annual";

export type SubscriptionStatus =
  | "trialing"
  | "active"
  | "past_due"
  | "canceled";

export interface Subscription extends Timestamps, TenantScoped {
  readonly id: SubscriptionId;
  readonly plan: PlanId;
  readonly interval: BillingInterval;
  readonly status: SubscriptionStatus;
  readonly seats: number;
  readonly currentPeriodStart: IsoTimestamp;
  readonly currentPeriodEnd: IsoTimestamp;
  readonly cancelAt: IsoTimestamp | null;
}

/** The resource dimensions every plan caps. Adding a field here ripples into
 *  `PLAN_LIMITS`, `BillingService`, the usage UI and the limit guards. */
export type LimitedResource =
  | "seats"
  | "projects"
  | "issuesPerProject"
  | "storageMb"
  | "apiRequestsPerHour"
  | "webhooks";

/** Result of a single quota check, returned by `BillingService.checkLimit`. */
export interface LimitCheck {
  readonly resource: LimitedResource;
  readonly plan: PlanId;
  readonly limit: number;
  readonly used: number;
  readonly remaining: number;
  readonly exceeded: boolean;
}

export interface Invoice extends Timestamps, TenantScoped {
  readonly id: string;
  readonly number: string;
  readonly amountCents: number;
  readonly currency: string;
  readonly periodStart: IsoTimestamp;
  readonly periodEnd: IsoTimestamp;
  readonly paidAt: IsoTimestamp | null;
}

export interface BillingSummary {
  readonly orgId: OrgId;
  readonly subscription: Subscription;
  readonly checks: readonly LimitCheck[];
  readonly upcomingInvoiceCents: number;
}

import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import {
  idColumn,
  softDeleteColumns,
  tenantColumns,
  timestampColumns,
} from "./_shared";

export const members = sqliteTable(
  "members",
  {
    id: idColumn(),
    ...tenantColumns,
    userId: text("user_id").notNull(),
    role: text("role", { enum: ["owner", "admin", "member", "viewer"] })
      .notNull()
      .default("member"),
    status: text("status", { enum: ["active", "invited", "suspended"] })
      .notNull()
      .default("active"),
    invitedBy: text("invited_by"),
    joinedAt: text("joined_at"),
    lastSeenAt: text("last_seen_at"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("members_org_user_idx").on(table.orgId, table.userId),
    index("members_org_role_idx").on(table.orgId, table.role),
  ],
);

export const invitations = sqliteTable(
  "invitations",
  {
    id: idColumn(),
    ...tenantColumns,
    email: text("email").notNull(),
    role: text("role", { enum: ["owner", "admin", "member", "viewer"] })
      .notNull()
      .default("member"),
    invitedBy: text("invited_by").notNull(),
    tokenHash: text("token_hash").notNull(),
    expiresAt: text("expires_at").notNull(),
    acceptedAt: text("accepted_at"),
    revokedAt: text("revoked_at"),
    ...timestampColumns,
  },
  (table) => [
    uniqueIndex("invitations_token_idx").on(table.tokenHash),
    index("invitations_org_email_idx").on(table.orgId, table.email),
  ],
);

export type MemberRow = typeof members.$inferSelect;
export type NewMemberRow = typeof members.$inferInsert;
export type InvitationRow = typeof invitations.$inferSelect;

/**
 * Webhook endpoints and their delivery attempts.
 */
import { and, asc, count, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, webhookDeliveries, webhookEndpoints } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { CreateWebhookInput, UpdateWebhookInput } from "@/schemas/webhook";
import type {
  WebhookDeliveryRow,
  WebhookEndpointRow,
} from "@/server/db/schema/webhooks";
import type { IsoTimestamp, OrgId, WebhookId } from "@/types/common";

export async function listEndpoints(
  orgId: OrgId,
): Promise<readonly WebhookEndpointRow[]> {
  return getDb()
    .select()
    .from(webhookEndpoints)
    .where(orgPredicate(webhookEndpoints.orgId, orgId))
    .orderBy(asc(webhookEndpoints.createdAt))
    .all();
}

export async function insertEndpoint(
  input: CreateWebhookInput,
  secret: string,
): Promise<WebhookEndpointRow> {
  const stamp = toIsoTimestamp(new Date());
  return getDb()
    .insert(webhookEndpoints)
    .values({
      id: newId(),
      orgId: input.orgId,
      url: input.url,
      secret,
      eventTypes: JSON.stringify(input.eventTypes),
      enabled: true,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
}

export async function updateEndpoint(
  input: UpdateWebhookInput,
): Promise<WebhookEndpointRow> {
  const row = getDb()
    .update(webhookEndpoints)
    .set({
      ...(input.url === undefined ? {} : { url: input.url }),
      ...(input.eventTypes === undefined
        ? {}
        : { eventTypes: JSON.stringify(input.eventTypes) }),
      ...(input.enabled === undefined ? {} : { enabled: input.enabled }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookEndpoints.orgId, input.orgId),
        eq(webhookEndpoints.id, input.webhookId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Webhook ${input.webhookId} not found`);
  return row;
}

export async function deleteEndpoint(
  orgId: OrgId,
  webhookId: WebhookId,
): Promise<void> {
  const db = getDb();
  db.delete(webhookDeliveries)
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.endpointId, webhookId),
      ),
    )
    .run();
  db.delete(webhookEndpoints)
    .where(
      and(
        orgPredicate(webhookEndpoints.orgId, orgId),
        eq(webhookEndpoints.id, webhookId),
      ),
    )
    .run();
}

/** The `webhooks` quota compares against this. */
export async function countEndpoints(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(webhookEndpoints)
    .where(orgPredicate(webhookEndpoints.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export async function enqueueDelivery(
  orgId: OrgId,
  endpointId: string,
  eventType: string,
  payload: string,
): Promise<WebhookDeliveryRow> {
  const stamp = toIsoTimestamp(new Date());
  return getDb()
    .insert(webhookDeliveries)
    .values({
      id: newId(),
      orgId,
      endpointId,
      eventType,
      payload,
      status: "pending",
      attempts: 0,
      lastError: null,
      deliveredAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
}

/**
 * Claims a batch for the delivery job. Cross-tenant on purpose — the queue is
 * drained by a background worker, not by a request — and the attempt counter
 * is bumped on claim so a crashed worker cannot retry forever.
 */
export async function claimPendingDeliveries(
  limit: number,
): Promise<readonly WebhookDeliveryRow[]> {
  const db = getDb();
  const pending = db
    .select()
    .from(webhookDeliveries)
    .where(eq(webhookDeliveries.status, "pending"))
    .orderBy(asc(webhookDeliveries.createdAt))
    .limit(Math.max(1, limit))
    .all();

  return pending.map((row) =>
    db
      .update(webhookDeliveries)
      .set({
        attempts: row.attempts + 1,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(eq(webhookDeliveries.id, row.id))
      .returning()
      .get(),
  );
}

export async function markDelivered(
  orgId: OrgId,
  deliveryId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(webhookDeliveries)
    .set({ status: "delivered", deliveredAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.id, deliveryId),
      ),
    )
    .run();
}

export async function markDeliveryFailed(
  orgId: OrgId,
  deliveryId: string,
  error: string,
): Promise<void> {
  getDb()
    .update(webhookDeliveries)
    .set({
      status: "failed",
      lastError: error.slice(0, 500),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.id, deliveryId),
      ),
    )
    .run();
}

