import type {
  IsoTimestamp,
  OrgId,
  ProjectId,
  UserId,
} from "./common";
import type { IssuePriority } from "./issue";

/** `daily` fires every calendar day; `weekly` fires on one ISO weekday. */
export type RecurrenceCadence = "daily" | "weekly";

/**
 * A standing rule the recurring-issue job turns into ordinary issues.
 *
 * Every date is a `YYYY-MM-DD` calendar day in `timezone`. `weekday` is the
 * ISO weekday (1 = Monday … 7 = Sunday) and is only set for weekly rules.
 */
export interface RecurringIssue {
  readonly id: string;
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly title: string;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
  readonly lastOccurrenceOn: string | null;
  readonly paused: boolean;
  readonly createdBy: UserId;
  readonly createdAt: IsoTimestamp;
  readonly updatedAt: IsoTimestamp;
}

