import { z } from "zod";
import { isCalendarDate, isIanaTimeZone } from "@/lib/date";
import { orgIdSchema, projectIdSchema, userIdSchema } from "./common";
import { issuePrioritySchema } from "./issue";

/**
 * A recurring-issue rule as submitted. Cadence and weekday must agree: weekly
 * rules name a weekday, daily rules must not. Dates and time zones are checked
 * against the runtime's calendar and Intl data, not just their shape.
 */
export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3, "give the recurring issue a title").max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: z.enum(["daily", "weekly"]),
    weekday: z.number().int().min(1).max(7).nullable().default(null),
    timezone: z.string().refine((value) => isIanaTimeZone(value), {
      message: "use an IANA time zone, e.g. Europe/Berlin",
    }),
    startsOn: z.string().refine((value) => isCalendarDate(value), {
      message: "use a real calendar date as YYYY-MM-DD",
    }),
  })
  .superRefine((value, ctx) => {
    if (value.cadence === "weekly" && value.weekday === null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "weekly rules need a weekday",
      });
    }
    if (value.cadence === "daily" && value.weekday !== null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "daily rules take no weekday",
      });
    }
  });

export type CreateRecurringIssueInput = z.input<typeof createRecurringIssueSchema>;

