const CALENDAR_DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * True when `value` is a real `YYYY-MM-DD` calendar day. The round trip through
 * `Date` is what rejects shapes that look right but do not exist, such as
 * `2026-02-30`.
 */
export function isCalendarDate(value: string): boolean {
  const match = CALENDAR_DATE_PATTERN.exec(value);
  if (match === null) return false;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/**
 * True when the runtime's Intl data knows `value` as a named time zone. Numeric
 * offsets such as `+05:00` are accepted by some runtimes but are not IANA names.
 */
export function isIanaTimeZone(value: string): boolean {
  if (value.startsWith("+") || value.startsWith("-")) return false;

  try {
    return (
      new Intl.DateTimeFormat("en-US", { timeZone: value }).resolvedOptions()
        .timeZone.length > 0
    );
  } catch {
    return false;
  }
}

/**
 * The calendar day (`YYYY-MM-DD`) that `instant` falls on in `timeZone`. A day
 * starts at the first instant whose local date is that day, so this is also the
 * latest day whose start has been reached by `instant`. DST is handled by the
 * zone data, so a day that begins at 01:00 after a midnight transition still
 * starts at its first real instant.
 */
export function localDateIn(instant: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(instant);

  const part = (type: "year" | "month" | "day"): string =>
    parts.find((candidate) => candidate.type === type)?.value ?? "";

  return `${part("year")}-${part("month")}-${part("day")}`;
}

