/**
 * Recurring-issue rules. Every read and write is scoped to one org, except the
 * job's sweep of active rules, which is cross-tenant like the webhook queue.
 */
import { and, asc, count, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toRecurringIssue } from "./_mappers";
import type { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import type { OrgId, UserId } from "@/types/common";
import type { RecurringIssue } from "@/types/recurring-issue";
import type { z } from "zod";

/** Creation order: ULIDs sort by creation time, so `id` breaks ties. */
const CREATION_ORDER = [
  asc(recurringIssues.createdAt),
  asc(recurringIssues.id),
] as const;

export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(...CREATION_ORDER)
    .all();
  return rows.map((row) => toRecurringIssue(row));
}

/** Every non-paused rule across all organizations, for the job's sweep. */
export async function listActiveRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(...CREATION_ORDER)
    .all();
  return rows.map((row) => toRecurringIssue(row));
}

export async function findRecurringIssueById(
  orgId: OrgId,
  recurringIssueId: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .get();
  return row ? toRecurringIssue(row) : null;
}

/** The plan's `recurringIssues` quota counts every rule, paused ones included. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export async function insertRecurringIssue(
  input: z.output<typeof createRecurringIssueSchema>,
  createdBy: UserId,
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      title: input.title,
      priority: input.priority,
      assigneeId: input.assigneeId,
      cadence: input.cadence,
      weekday: input.weekday,
      timezone: input.timezone,
      startsOn: input.startsOn,
      lastOccurrenceOn: null,
      paused: false,
      createdBy,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toRecurringIssue(row);
}

export async function setRecurringIssuePaused(
  orgId: OrgId,
  recurringIssueId: string,
  paused: boolean,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Recurring issue ${recurringIssueId} not found`);
  return toRecurringIssue(row);
}

/** Records the occurrence day an issue was filed for, so it is never refiled. */
export async function recordRecurringOccurrence(
  orgId: OrgId,
  recurringIssueId: string,
  occurrenceOn: string,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ lastOccurrenceOn: occurrenceOn, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Recurring issue ${recurringIssueId} not found`);
  return toRecurringIssue(row);
}

