/**
 * Files the latest due occurrence of every active recurring-issue rule as an ordinary issue, on behalf of the rule's creator.
 *
 * Must call (do not reimplement): localDateIn, createIssue, PermissionDeniedError
 */
import { localDateIn } from "@/lib/date";
import { createLogger } from "@/lib/logger";
import { PermissionDeniedError } from "@/lib/permissions";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import * as issueService from "@/server/services/issue-service";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

/**
 * One pass per scheduler tick. Each active rule files at most one issue, for
 * the latest occurrence that has started by `now`. Missed occurrences are not
 * back-filled, so a rule that was idle for a while catches up with one issue.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        if (await fileLatestOccurrence(rule, now)) {
          result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Returns true when an issue was filed. The occurrence is recorded only after
 * the issue exists, so a refused creation is simply tried again on a later run.
 */
async function fileLatestOccurrence(
  rule: RecurringIssue,
  now: Date,
): Promise<boolean> {
  const occurrence = latestStartedOccurrence(rule, now);
  if (occurrence === null) return false;
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return false;
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) {
    throw new Error(`Project ${rule.projectId} was not found`);
  }
  if (project.archivedAt !== null) return false;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  if (creator === null || creator.status !== "active") {
    await recurringIssueRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    return false;
  }

  const actor: Actor = {
    userId: rule.createdBy,
    orgId: rule.orgId,
    role: creator.role,
  };
