import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { ZodError } from "zod";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as recurringIssueService from "@/server/services/recurring-issue-service";
import { NotFoundError } from "@/server/services/_support";
import type { Actor } from "@/types/member";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let jobTenant: Tenant;

const MISSING = "01ARZ3NDEKTSV4RRFFQ69G5FAV";
const NOW = new Date("2026-03-05T10:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("rec");
  other = await createTenant("recother");
  jobTenant = await createTenant("recjobs");
});

afterAll(() => cleanup());

function ruleInput(
  t: Tenant,
  overrides: Partial<CreateRecurringIssueInput> = {},
): CreateRecurringIssueInput {
  return {
    orgId: t.org.id,
    projectId: t.project.id,
    title: "Daily triage",
    cadence: "daily",
    timezone: "UTC",
    startsOn: "2026-03-01",
    ...overrides,
  } as CreateRecurringIssueInput;
}

async function listRules(t: Tenant) {
  return recurringIssueService.listRecurringIssues(t.actors.owner, t.org.id);
}

async function titlesIn(projectId: string): Promise<string[]> {
  const page = await issueRepo.listIssues({
    orgId: jobTenant.org.id,
    projectId,
    limit: 100,
  } as never);
  return page.items.map((issue) => issue.title);
}

async function insertMemberUser(email: string, role: "member" | "viewer" = "member") {
  const user = await userRepo.insertUser({ email, name: email, passwordHash: "seed" });
  await memberRepo.insertMember(jobTenant.org.id, user.id, role, null);
  return user;
}

describe("createRecurringIssueSchema", () => {
  it("applies defaults for priority, assignee and weekday", () => {
    expect(createRecurringIssueSchema.parse(ruleInput(tenant))).toMatchObject({
      priority: "none",
      assigneeId: null,
      weekday: null,
    });
  });

  it("requires a weekday for weekly rules and a valid weekday range", () => {
    expect(() =>
      createRecurringIssueSchema.parse(ruleInput(tenant, { cadence: "weekly" })),
    ).toThrow(ZodError);
    expect(() =>
      createRecurringIssueSchema.parse(ruleInput(tenant, { cadence: "weekly", weekday: 0 })),
    ).toThrow(ZodError);
    expect(() =>
      createRecurringIssueSchema.parse(ruleInput(tenant, { cadence: "weekly", weekday: 8 })),
    ).toThrow(ZodError);
    expect(
      createRecurringIssueSchema.parse(ruleInput(tenant, { cadence: "weekly", weekday: 7 })).weekday,
    ).toBe(7);
  });

  it("forbids a weekday on daily rules", () => {
    expect(() =>
      createRecurringIssueSchema.parse(ruleInput(tenant, { weekday: 3 })),
    ).toThrow(ZodError);
  });

  it("rejects unknown and numeric time zones, accepts named ones", () => {
    expect(() => createRecurringIssueSchema.parse(ruleInput(tenant, { timezone: "Mars/Olympus" }))).toThrow(ZodError);
    expect(() => createRecurringIssueSchema.parse(ruleInput(tenant, { timezone: "+05:00" }))).toThrow(ZodError);
    expect(createRecurringIssueSchema.parse(ruleInput(tenant, { timezone: "America/New_York" })).timezone).toBe("America/New_York");
  });

  it("rejects impossible calendar dates", () => {
    expect(() => createRecurringIssueSchema.parse(ruleInput(tenant, { startsOn: "2026-02-30" }))).toThrow(ZodError);
    expect(() => createRecurringIssueSchema.parse(ruleInput(tenant, { startsOn: "2026-2-3" }))).toThrow(ZodError);
    expect(createRecurringIssueSchema.parse(ruleInput(tenant, { startsOn: "2028-02-29" })).startsOn).toBe("2028-02-29");
  });

  it("bounds the title to 3-180 characters", () => {
    expect(() => createRecurringIssueSchema.parse(ruleInput(tenant, { title: "ab" }))).toThrow(ZodError);
    expect(() => createRecurringIssueSchema.parse(ruleInput(tenant, { title: "x".repeat(181) }))).toThrow(ZodError);
    expect(createRecurringIssueSchema.parse(ruleInput(tenant, { title: "x".repeat(180) })).title).toHaveLength(180);
  });
});

describe("createRecurringIssue", () => {
  it("stores an unpaused rule that has never fired", async () => {
    const rule = await recurringIssueService.createRecurringIssue(
      tenant.actors.member,
      ruleInput(tenant, { priority: "high" }),
    );
    expect(rule).toMatchObject({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      title: "Daily triage",
      priority: "high",
      assigneeId: null,
      cadence: "daily",
      weekday: null,
      timezone: "UTC",
      startsOn: "2026-03-01",
      lastOccurrenceOn: null,
      paused: false,
      createdBy: tenant.userIds.member,
    });
  });

  it("refuses another organization's rule as a tenant-scope error", async () => {
    await expect(
      recurringIssueService.createRecurringIssue(tenant.actors.member, ruleInput(other)),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("denies viewers", async () => {
    await expect(
      recurringIssueService.createRecurringIssue(tenant.actors.viewer, ruleInput(tenant)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("reports a missing project as not found", async () => {
    await expect(
      recurringIssueService.createRecurringIssue(
        tenant.actors.member,
        ruleInput(tenant, { projectId: MISSING as never }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses archived projects", async () => {
    const archived = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Old",
      slug: "old",
      key: "OLD",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    await projectRepo.archiveProject(tenant.org.id, archived.id);
    await expect(
      recurringIssueService.createRecurringIssue(
        tenant.actors.member,
        ruleInput(tenant, { projectId: archived.id }),
      ),
    ).rejects.toThrow();
  });

  it("requires an active member as assignee", async () => {
    await expect(
      recurringIssueService.createRecurringIssue(
        tenant.actors.member,
        ruleInput(tenant, { assigneeId: other.userIds.owner }),
      ),
    ).rejects.toThrow();
    const ok = await recurringIssueService.createRecurringIssue(
      tenant.actors.member,
      ruleInput(tenant, { title: "Assigned", assigneeId: tenant.userIds.admin }),
    );
    expect(ok.assigneeId).toBe(tenant.userIds.admin);
  });

  it("stores nothing when the input is invalid", async () => {
    const before = (await listRules(tenant)).length;
    await expect(
      recurringIssueService.createRecurringIssue(tenant.actors.member, ruleInput(tenant, { title: "ab" })),
    ).rejects.toBeInstanceOf(ZodError);
    expect((await listRules(tenant)).length).toBe(before);
  });
});

describe("plan quota for recurring issues", () => {
  it("free plan allows none", async () => {
    const free = await createTenant("recfree", "free");
    await expect(
      recurringIssueService.createRecurringIssue(free.actors.member, ruleInput(free)),
    ).rejects.toThrow();
    expect(await listRules(free)).toHaveLength(0);
  });

  it("starter caps at three, counting paused rules", async () => {
    const starter = await createTenant("recstarter", "starter");
    const first = await recurringIssueService.createRecurringIssue(starter.actors.member, ruleInput(starter, { title: "Rule one" }));
    for (const title of ["Rule two", "Rule three"]) {
      await recurringIssueService.createRecurringIssue(starter.actors.member, ruleInput(starter, { title }));
    }
    await recurringIssueService.setRecurringIssuePaused(starter.actors.owner, {
      orgId: starter.org.id,
      recurringIssueId: first.id,
      paused: true,
    });
    await expect(
      recurringIssueService.createRecurringIssue(starter.actors.member, ruleInput(starter, { title: "Rule four" })),
    ).rejects.toThrow();
    expect(await listRules(starter)).toHaveLength(3);
  });
});

describe("pausing and listing", () => {
  it("pauses and resumes a rule", async () => {
    const rule = (await listRules(tenant))[0]!;
    const paused = await recurringIssueService.setRecurringIssuePaused(tenant.actors.member, {
      orgId: tenant.org.id,
      recurringIssueId: rule.id,
      paused: true,
    });
    expect(paused.paused).toBe(true);
    const resumed = await recurringIssueService.setRecurringIssuePaused(tenant.actors.member, {
      orgId: tenant.org.id,
      recurringIssueId: rule.id,
      paused: false,
    });
    expect(resumed.paused).toBe(false);
  });

  it("refuses another organization and unknown ids", async () => {
    const rule = (await listRules(tenant))[0]!;
    await expect(
      recurringIssueService.setRecurringIssuePaused(tenant.actors.member, {
        orgId: other.org.id,
        recurringIssueId: rule.id,
        paused: true,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      recurringIssueService.setRecurringIssuePaused(tenant.actors.member, {
        orgId: tenant.org.id,
        recurringIssueId: "nope",
        paused: true,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("lists in creation order and enforces tenant scope", async () => {
    const rules = await recurringIssueService.listRecurringIssues(tenant.actors.viewer, tenant.org.id);
    const titles = rules.map((rule) => rule.title);
    expect(titles[0]).toBe("Daily triage");
    expect(titles).toContain("Assigned");
    await expect(
      recurringIssueService.listRecurringIssues(other.actors.viewer, tenant.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("runRecurringIssueJob", () => {
  it("files the latest started occurrence once and never back-fills", async () => {
    await recurringIssueService.createRecurringIssue(
      jobTenant.actors.member,
      ruleInput(jobTenant, { title: "Daily triage", priority: "high" }),
    );

    const first = await runRecurringIssueJob(NOW);
    expect(first.kind).toBe("recurring-issues");
    expect(first.processed).toBeGreaterThan(0);

    const issues = await issueRepo.listIssues({ orgId: jobTenant.org.id, projectId: jobTenant.project.id, limit: 100 } as never);
    const filed = issues.items.find((issue) => issue.title === "Daily triage (2026-03-05)");
    expect(filed).toBeDefined();
    expect(filed).toMatchObject({ status: "backlog", priority: "high", authorId: jobTenant.userIds.member, assigneeId: null, description: null, dueAt: null });

    const rule = (await listRules(jobTenant)).find((r) => r.title === "Daily triage")!;
    expect(rule.lastOccurrenceOn).toBe("2026-03-05");

    const again = await runRecurringIssueJob(NOW);
    expect(again.processed).toBe(0);

    await runRecurringIssueJob(new Date("2026-03-07T10:00:00.000Z"));
    const titles = await titlesIn(jobTenant.project.id);
    expect(titles).toContain("Daily triage (2026-03-07)");
    expect(titles.some((title) => title === "Daily triage (2026-03-06)")).toBe(false);
  });

  it("uses the rule's own time zone and daylight-saving transitions", async () => {
    await recurringIssueService.createRecurringIssue(
      jobTenant.actors.member,
      ruleInput(jobTenant, { title: "NY daily", timezone: "America/New_York", startsOn: "2026-03-08" }),
    );

    // 23:30 on 7 March in New York: day 8 has not started yet.
    await runRecurringIssueJob(new Date("2026-03-08T04:30:00.000Z"));
    expect((await titlesIn(jobTenant.project.id)).some((t) => t.startsWith("NY daily"))).toBe(false);

    // 08:00 EDT on 8 March: day 8 has started.
    await runRecurringIssueJob(new Date("2026-03-08T12:00:00.000Z"));
    expect(await titlesIn(jobTenant.project.id)).toContain("NY daily (2026-03-08)");
  });

  it("weekly rules file the latest matching weekday, and not before startsOn", async () => {
    await recurringIssueService.createRecurringIssue(
      jobTenant.actors.member,
      ruleInput(jobTenant, { title: "Monday planning", cadence: "weekly", weekday: 1 }),
    );
    await recurringIssueService.createRecurringIssue(
      jobTenant.actors.member,
      ruleInput(jobTenant, { title: "Late start", cadence: "weekly", weekday: 1, startsOn: "2026-03-09" }),
    );

    await runRecurringIssueJob(new Date("2026-03-08T10:00:00.000Z"));
    const titles = await titlesIn(jobTenant.project.id);
    expect(titles).toContain("Monday planning (2026-03-02)");
    expect(titles.some((t) => t.startsWith("Late start"))).toBe(false);
  });

  it("skips archived projects and files once they are restored", async () => {
    const archived = await projectRepo.insertProject({
      orgId: jobTenant.org.id,
      name: "Archive me",
      slug: "archive-me",
      key: "ARCH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const rule = await recurringIssueService.createRecurringIssue(
      jobTenant.actors.member,
      ruleInput(jobTenant, { title: "Archived daily", projectId: archived.id }),
    );
    await projectRepo.archiveProject(jobTenant.org.id, archived.id);

    await runRecurringIssueJob(NOW);
    expect(await titlesIn(archived.id)).toHaveLength(0);
    expect((await listRules(jobTenant)).find((r) => r.id === rule.id)!.lastOccurrenceOn).toBeNull();

    await projectRepo.restoreProject(jobTenant.org.id, archived.id);
    await runRecurringIssueJob(NOW);
    expect(await titlesIn(archived.id)).toEqual(["Archived daily (2026-03-05)"]);
  });

  it("pauses a rule whose creator has left the organization", async () => {
    const user = await insertMemberUser("gone@recjobs.test");
    const actor: Actor = { userId: user.id, orgId: jobTenant.org.id, role: "member" };
    const rule = await recurringIssueService.createRecurringIssue(actor, ruleInput(jobTenant, { title: "Creator gone" }));
    const member = (await memberRepo.findMember(jobTenant.org.id, user.id))!;
    await memberRepo.archiveMember(jobTenant.org.id, member.id);

    await runRecurringIssueJob(NOW);
    expect((await titlesIn(jobTenant.project.id)).some((t) => t.startsWith("Creator gone"))).toBe(false);
    expect((await listRules(jobTenant)).find((r) => r.id === rule.id)!.paused).toBe(true);
  });

  it("pauses a rule whose creator can no longer create issues", async () => {
    const user = await insertMemberUser("demoted@recjobs.test");
    const actor: Actor = { userId: user.id, orgId: jobTenant.org.id, role: "member" };
    const rule = await recurringIssueService.createRecurringIssue(actor, ruleInput(jobTenant, { title: "Demoted" }));
    const member = (await memberRepo.findMember(jobTenant.org.id, user.id))!;
    await memberRepo.updateMemberRole(jobTenant.org.id, member.id, "viewer");

    await runRecurringIssueJob(NOW);
    expect((await titlesIn(jobTenant.project.id)).some((t) => t.startsWith("Demoted"))).toBe(false);
    expect((await listRules(jobTenant)).find((r) => r.id === rule.id)!.paused).toBe(true);
  });

  it("unassigns when the assignee has left and keeps an active assignee", async () => {
    const leaver = await insertMemberUser("leaver@recjobs.test");
    await recurringIssueService.createRecurringIssue(
      jobTenant.actors.member,
      ruleInput(jobTenant, { title: "Left assignee", assigneeId: leaver.id }),
    );
    await recurringIssueService.createRecurringIssue(
      jobTenant.actors.member,
      ruleInput(jobTenant, { title: "Kept assignee", assigneeId: jobTenant.userIds.viewer }),
    );
    const leaverMember = (await memberRepo.findMember(jobTenant.org.id, leaver.id))!;
    await memberRepo.archiveMember(jobTenant.org.id, leaverMember.id);

    await runRecurringIssueJob(NOW);
    const issues = await issueRepo.listIssues({ orgId: jobTenant.org.id, projectId: jobTenant.project.id, limit: 100 } as never);
    expect(issues.items.find((i) => i.title === "Left assignee (2026-03-05)")?.assigneeId).toBeNull();
    expect(issues.items.find((i) => i.title === "Kept assignee (2026-03-05)")?.assigneeId).toBe(jobTenant.userIds.viewer);
  });

  it("files through the normal issue path, so issue.created is published", async () => {
    const seen: { title?: string; actorId?: string | null }[] = [];
    const off = subscribe("issue.created", async (payload) => {
      seen.push({ title: (payload as { title?: string }).title, actorId: (payload as { actorId?: string | null }).actorId });
    });

    try {
      await recurringIssueService.createRecurringIssue(
        jobTenant.actors.member,
        ruleInput(jobTenant, { title: "Event rule" }),
      );
      await runRecurringIssueJob(NOW);
    } finally {
      off();
    }

    expect(seen.find((event) => event.title === "Event rule (2026-03-05)")?.actorId).toBe(jobTenant.userIds.member);
  });
});

