function ruleInput(
  t: Tenant,
  overrides: Partial<CreateRecurringIssueInput> = {},
): CreateRecurringIssueInput {
  return {
    orgId: t.org.id,
    projectId: t.project.id,
    title: "Daily triage",
    cadence: "daily",
    timezone: "UTC",
    startsOn: "2026-03-01",
